export class ResourceScope {
    disposed = false;
    label;
    resources = new Set();
    onDispose;
    constructor(options = {}) { this.label = options.label; this.onDispose = options.onDispose; }
    track(resource) {
        if (this.disposed) {
            resource.dispose();
            throw new Error(`Cannot track a resource in disposed ResourceScope${this.label ? ` (${this.label})` : ''}.`);
        }
        this.resources.add(resource);
        return resource;
    }
    release(resource) { this.resources.delete(resource); }
    has(resource) { return this.resources.has(resource); }
    dispose() { if (this.disposed)
        return; this.disposed = true; for (const resource of [...this.resources].reverse())
        resource.dispose(); this.resources.clear(); this.onDispose?.(this); }
    get size() { return this.resources.size; }
}
export class ResourceManager {
    disposed = false;
    scopes = new Set();
    createScope(label) {
        if (this.disposed)
            throw new Error('ResourceManager is disposed.');
        const scope = new ResourceScope({ label, onDispose: value => this.scopes.delete(value) });
        this.scopes.add(scope);
        return scope;
    }
    get stats() { let trackedResources = 0; for (const scope of this.scopes)
        trackedResources += scope.size; return { scopes: this.scopes.size, trackedResources }; }
    dispose() { if (this.disposed)
        return; this.disposed = true; for (const scope of [...this.scopes])
        scope.dispose(); this.scopes.clear(); }
}